package dev.proofcode.control.data;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.stereotype.Component;
import java.sql.*;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.Consumer;

/** Bounded PostgreSQL IR. Every value is bound; identifiers come from an inspected allowlist. */
@Component
public class PostgresDataAdapter implements DataAdapter {
    private final DataSecrets secrets;private final ObjectMapper json;
    public PostgresDataAdapter(DataSecrets secrets,ObjectMapper json){this.secrets=secrets;this.json=json;}
    protected Connection connect(DataResource r)throws SQLException {JsonNode s=secrets.resolve(r.secretRef);String url=DataPolicy.required(s,"url");if(!url.startsWith("jdbc:postgresql:"))throw DataPolicy.bad("only PostgreSQL JDBC endpoints are supported");return DriverManager.getConnection(url,DataPolicy.required(s,"user"),s.path("password").asText());}
    @Override public JsonNode schema(DataResource r){
        try(Connection c=connect(r)){DatabaseMetaData md=c.getMetaData();ArrayNode tables=json.createArrayNode();JsonNode allowed=json.readTree(r.allowedSchemas);List<String> schemas=new ArrayList<>();allowed.forEach(n->schemas.add(n.asText()));Collections.sort(schemas);
            for(String schema:schemas){DataPolicy.identifier(schema);try(ResultSet ts=md.getTables(null,schema,null,new String[]{"TABLE"})){List<String> names=new ArrayList<>();while(ts.next())names.add(ts.getString("TABLE_NAME"));Collections.sort(names);for(String table:names){if(!table.matches("[A-Za-z_][A-Za-z0-9_]{0,62}"))continue;ObjectNode t=tables.addObject().put("schema",schema).put("name",table);ArrayNode columns=t.putArray("columns");
                try(ResultSet cols=md.getColumns(null,schema,table,null)){while(cols.next()){String column=cols.getString("COLUMN_NAME");if(!column.matches("[A-Za-z_][A-Za-z0-9_]{0,62}"))continue;boolean computed="YES".equals(cols.getString("IS_GENERATEDCOLUMN")),autoIncrement="YES".equals(cols.getString("IS_AUTOINCREMENT"));ObjectNode col=columns.addObject().put("name",column).put("type",cols.getString("TYPE_NAME")).put("jdbcType",cols.getInt("DATA_TYPE")).put("nullable",cols.getInt("NULLABLE")!=DatabaseMetaData.columnNoNulls).put("generated",computed||autoIncrement).put("computed",computed).put("autoIncrement",autoIncrement);String def=cols.getString("COLUMN_DEF"),comment=cols.getString("REMARKS");if(def==null)col.putNull("defaultValue");else col.put("defaultValue",def);if(comment!=null)col.put("comment",comment);}}
                TreeMap<Integer,String> primary=new TreeMap<>();try(ResultSet pk=md.getPrimaryKeys(null,schema,table)){while(pk.next())primary.put(pk.getInt("KEY_SEQ"),pk.getString("COLUMN_NAME"));}ArrayNode primaryKeys=t.putArray("primaryKey");primary.values().forEach(primaryKeys::add);
                TreeMap<String,ObjectNode> foreign=new TreeMap<>();try(ResultSet fk=md.getImportedKeys(null,schema,table)){while(fk.next()){String name=Objects.toString(fk.getString("FK_NAME"),fk.getString("PKTABLE_NAME"));ObjectNode entry=foreign.get(name);if(entry==null){entry=json.createObjectNode().put("name",name).put("referencesSchema",fk.getString("PKTABLE_SCHEM")).put("referencesTable",fk.getString("PKTABLE_NAME"));entry.putArray("columns");entry.putArray("referencesColumns");foreign.put(name,entry);}((ArrayNode)entry.get("columns")).add(fk.getString("FKCOLUMN_NAME"));((ArrayNode)entry.get("referencesColumns")).add(fk.getString("PKCOLUMN_NAME"));}}ArrayNode foreignKeys=t.putArray("foreignKeys");foreign.values().forEach(foreignKeys::add);
                TreeMap<String,ObjectNode> indexes=new TreeMap<>();try(ResultSet ix=md.getIndexInfo(null,schema,table,false,true)){while(ix.next()){String name=ix.getString("INDEX_NAME"),col=ix.getString("COLUMN_NAME");if(name==null||col==null)continue;ObjectNode entry=indexes.computeIfAbsent(name,n->{ObjectNode e=json.createObjectNode().put("name",n);e.putArray("columns");return e;});entry.put("unique",!ix.getBoolean("NON_UNIQUE"));((ArrayNode)entry.get("columns")).add(col);}}ArrayNode indexList=t.putArray("indexes");indexes.values().forEach(indexList::add);
            }}}
            return json.createObjectNode().set("tables",tables);
        }catch(Exception e){throw DataPolicy.bad("schema inspection failed; verify source configuration and permissions");}
    }
    private JsonNode table(JsonNode schema,String sn,String name){for(JsonNode t:schema.path("tables"))if(sn.equals(t.path("schema").asText())&&name.equals(t.path("name").asText()))return t;throw DataPolicy.bad("table is absent from the approved schema snapshot");}
    private Map<String,JsonNode> columns(JsonNode table){Map<String,JsonNode> cols=new LinkedHashMap<>();table.path("columns").forEach(c->cols.put(c.path("name").asText(),c));return cols;}
    @Override public Compiled compile(DataResource r,JsonNode schema,JsonNode ir){
        if("migration".equals(ir.path("kind").asText()))return migration(r,schema,ir);
        DataPolicy.fields(ir,"kind","schema","table","select","filters","where","limit","offset","orderBy","includeRowHashes","operation","values","expectedRows","expectedBeforeHash");
        String kind=DataPolicy.required(ir,"kind"),sn=DataPolicy.required(ir,"schema"),name=DataPolicy.required(ir,"table");JsonNode meta=table(schema,sn,name);Map<String,JsonNode> cols=columns(meta);
        String target=DataPolicy.identifier(sn)+"."+DataPolicy.identifier(name);List<Object> params=new ArrayList<>();String sql;
        if(kind.equals("query")){
            for(String field:List.of("operation","values","expectedRows","expectedBeforeHash"))if(ir.has(field))throw DataPolicy.bad("query cannot contain mutation fields");JsonNode select=ir.get("select");if(select==null||!select.isArray()||select.isEmpty()||select.size()>64)throw DataPolicy.bad("select requires 1 to 64 columns");List<String> selected=new ArrayList<>();Set<String> selectedNames=new HashSet<>();for(JsonNode c:select){if(!c.isTextual()||!selectedNames.add(c.asText()))throw DataPolicy.bad("selected columns must be distinct strings");selected.add(column(cols,c.asText()));}
            if(ir.has("includeRowHashes")&&!ir.get("includeRowHashes").isBoolean())throw DataPolicy.bad("includeRowHashes must be boolean");if(ir.path("includeRowHashes").asBoolean()&&!selectedNames.equals(cols.keySet()))throw DataPolicy.bad("row hashes require every table column");
            sql="SELECT "+String.join(", ",selected)+" FROM "+target+filters(ir,cols,params)+ordering(ir,cols,meta)+" LIMIT "+DataPolicy.integer(ir,"limit",1,1000,100)+" OFFSET "+DataPolicy.integer(ir,"offset",0,100000,0);
        }else if(kind.equals("mutation")){
            for(String field:List.of("select","limit","offset","orderBy","includeRowHashes"))if(ir.has(field))throw DataPolicy.bad("mutation cannot contain query fields");String op=DataPolicy.required(ir,"operation");if(!ir.has("expectedRows"))throw DataPolicy.bad("expectedRows is required");DataPolicy.integer(ir,"expectedRows",0,1000,-1);
            if(meta.path("primaryKey").isEmpty())throw DataPolicy.bad("editable/recoverable rows require a primary key");
            if(ir.has("expectedBeforeHash")&&!DataPolicy.required(ir,"expectedBeforeHash").matches("[a-f0-9]{64}"))throw DataPolicy.bad("invalid expectedBeforeHash");
            if(op.equals("delete")){if(ir.has("values"))throw DataPolicy.bad("delete cannot contain values");sql="DELETE FROM "+target+requiredFilters(ir,cols,params);}
            else if(op.equals("insert")||op.equals("update")){JsonNode values=ir.get("values");if(values==null||!values.isObject()||values.isEmpty()||values.size()>64)throw DataPolicy.bad("values must contain 1 to 64 columns");List<String> keys=new ArrayList<>();values.fieldNames().forEachRemaining(keys::add);Collections.sort(keys);List<String> assignments=new ArrayList<>();for(String key:keys){String col=column(cols,key);if(cols.get(key).path("generated").asBoolean())throw DataPolicy.bad("generated columns are immutable");if(op.equals("update")&&contains(meta.path("primaryKey"),key))throw DataPolicy.bad("primary key updates require a separate reviewed migration");params.add(typed(cols.get(key),values.get(key),true));assignments.add(op.equals("update")?col+" = ?":col);}
                if(op.equals("insert")){if(ir.has("filters")||ir.has("where")||ir.has("expectedBeforeHash"))throw DataPolicy.bad("insert cannot contain filters or a row hash");if(ir.path("expectedRows").asInt()!=1)throw DataPolicy.bad("single-row insert requires expectedRows=1");sql="INSERT INTO "+target+" ("+String.join(", ",assignments)+") VALUES ("+String.join(", ",Collections.nCopies(keys.size(),"?"))+")";}else sql="UPDATE "+target+" SET "+String.join(", ",assignments)+requiredFilters(ir,cols,params);
            }else throw DataPolicy.bad("unsupported mutation operation");
        }else throw DataPolicy.bad("unsupported SQL IR kind");
        ObjectNode intent=(ObjectNode)ir.deepCopy();intent.set("_table",meta.deepCopy());return new Compiled(kind,sql,sql,Collections.unmodifiableList(new ArrayList<>(params)),intent);
    }
    private boolean contains(JsonNode array,String text){for(JsonNode n:array)if(n.asText().equals(text))return true;return false;}
    private String column(Map<String,JsonNode> cols,String name){if(!cols.containsKey(name))throw DataPolicy.bad("unknown column");return DataPolicy.identifier(name);}
    private String ordering(JsonNode ir,Map<String,JsonNode> cols,JsonNode meta){List<String> order=new ArrayList<>();Set<String> seen=new HashSet<>();JsonNode list=ir.get("orderBy");if(list!=null){if(!list.isArray()||list.size()>8)throw DataPolicy.bad("orderBy must contain at most 8 columns");for(JsonNode n:list){DataPolicy.fields(n,"column","direction");String c=DataPolicy.required(n,"column"),d=n.path("direction").asText("asc");if(!Set.of("asc","desc").contains(d)||!seen.add(c))throw DataPolicy.bad("invalid or duplicate order column");order.add(column(cols,c)+" "+d.toUpperCase(Locale.ROOT));}}
        for(JsonNode pk:meta.path("primaryKey"))if(seen.add(pk.asText()))order.add(column(cols,pk.asText())+" ASC");return order.isEmpty()?"":" ORDER BY "+String.join(", ",order);
    }
    private String requiredFilters(JsonNode ir,Map<String,JsonNode> cols,List<Object> params){String where=filters(ir,cols,params);if(where.isEmpty())throw DataPolicy.bad("mutation requires a nonempty WHERE");return where;}
    private String filters(JsonNode ir,Map<String,JsonNode> cols,List<Object> params){if(ir.has("filters")&&ir.has("where"))throw DataPolicy.bad("use either filters or where");if(ir.has("where"))return " WHERE "+predicate(ir.get("where"),cols,params,new int[]{0},0);JsonNode list=ir.get("filters");if(list==null)return "";if(!list.isArray()||list.size()>32)throw DataPolicy.bad("filters must contain at most 32 predicates");List<String> parts=new ArrayList<>();for(JsonNode p:list)parts.add(predicate(p,cols,params,new int[]{0},0));return parts.isEmpty()?"":" WHERE "+String.join(" AND ",parts);}
    private String predicate(JsonNode p,Map<String,JsonNode> cols,List<Object> params,int[] count,int depth){if(depth>4||++count[0]>64)throw DataPolicy.bad("filter expression exceeds its bound");String op=DataPolicy.required(p,"operator");if(Set.of("and","or").contains(op)){DataPolicy.fields(p,"operator","conditions");JsonNode children=p.get("conditions");if(children==null||!children.isArray()||children.isEmpty()||children.size()>32)throw DataPolicy.bad("boolean filters require 1 to 32 conditions");List<String> parts=new ArrayList<>();for(JsonNode child:children)parts.add(predicate(child,cols,params,count,depth+1));return "("+String.join(op.equals("and")?" AND ":" OR ",parts)+")";}
        DataPolicy.fields(p,"column","operator","value");String name=DataPolicy.required(p,"column"),col=column(cols,name);if(Set.of("is_null","is_not_null").contains(op)){if(p.has("value"))throw DataPolicy.bad("null checks cannot contain a value");return col+(op.equals("is_null")?" IS NULL":" IS NOT NULL");}
        if(op.equals("in")){JsonNode values=p.get("value");if(values==null||!values.isArray()||values.isEmpty()||values.size()>100)throw DataPolicy.bad("IN requires 1 to 100 non-null scalar values");for(JsonNode v:values){if(v.isNull())throw DataPolicy.bad("IN cannot contain null");params.add(typed(cols.get(name),v,false));}return col+" IN ("+String.join(", ",Collections.nCopies(values.size(),"?"))+")";}
        String sql=switch(op){case "eq"->"=";case "ne"->"<>";case "lt"->"<";case "lte"->"<=";case "gt"->">";case "gte"->">=";default->throw DataPolicy.bad("unsupported filter operator");};if(!p.has("value")||p.get("value").isNull())throw DataPolicy.bad("filter value is required and non-null");params.add(typed(cols.get(name),p.get("value"),false));return col+" "+sql+" ?";
    }
    private Object typed(JsonNode col,JsonNode v,boolean writing){if(v==null||v.isNull()){if(writing&&!col.path("nullable").asBoolean(true))throw DataPolicy.bad("non-null column cannot receive null");return null;}int type=col.path("jdbcType").asInt(Types.VARCHAR);try{return switch(type){
        case Types.TINYINT,Types.SMALLINT,Types.INTEGER,Types.BIGINT->{long value;if(v.isIntegralNumber()&&v.canConvertToLong())value=v.longValue();else if(v.isTextual()&&v.asText().matches("-?(0|[1-9][0-9]{0,18})"))value=Long.parseLong(v.asText());else throw new IllegalArgumentException();if(type==Types.INTEGER&&(value<Integer.MIN_VALUE||value>Integer.MAX_VALUE)||type==Types.SMALLINT&&(value<Short.MIN_VALUE||value>Short.MAX_VALUE)||type==Types.TINYINT&&(value<Byte.MIN_VALUE||value>Byte.MAX_VALUE))throw new IllegalArgumentException();yield value;}
        case Types.NUMERIC,Types.DECIMAL,Types.FLOAT,Types.REAL,Types.DOUBLE->{BigDecimal value;if(v.isNumber())value=v.decimalValue();else if(v.isTextual()&&v.asText().length()<=1024&&v.asText().matches("[+-]?([0-9]+(\\.[0-9]*)?|\\.[0-9]+)([eE][+-]?[0-9]{1,4})?"))value=new BigDecimal(v.asText());else throw new IllegalArgumentException();if(value.precision()>1000||Math.abs((long)value.scale())>1000)throw new IllegalArgumentException();yield value;}
        case Types.BOOLEAN,Types.BIT->{if(!v.isBoolean())throw new IllegalArgumentException();yield v.booleanValue();}
        case Types.DATE->{if(!v.isTextual())throw new IllegalArgumentException();yield java.sql.Date.valueOf(LocalDate.parse(v.asText()));}
        case Types.TIME->{if(!v.isTextual())throw new IllegalArgumentException();yield java.sql.Time.valueOf(LocalTime.parse(v.asText()));}
        case Types.TIMESTAMP->{if(!v.isTextual())throw new IllegalArgumentException();yield java.sql.Timestamp.valueOf(LocalDateTime.parse(v.asText().replace(' ','T')));}
        case Types.TIMESTAMP_WITH_TIMEZONE->{if(!v.isTextual())throw new IllegalArgumentException();yield OffsetDateTime.parse(v.asText());}
        case Types.CHAR,Types.VARCHAR,Types.LONGVARCHAR,Types.NCHAR,Types.NVARCHAR,Types.LONGNVARCHAR->{if(!v.isTextual()||v.asText().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new IllegalArgumentException();yield v.asText();}
        case Types.OTHER->{if(!v.isTextual()||!col.path("type").asText().equalsIgnoreCase("uuid"))throw new IllegalArgumentException();yield UUID.fromString(v.asText());}
        default->throw new IllegalArgumentException();};}catch(Exception e){throw DataPolicy.bad("value does not match column type: "+col.path("name").asText());}}
    @Override public Outcome execute(DataResource r,Compiled p){return execute(r,p,null,value->{});}
    @Override public Outcome execute(DataResource r,Compiled p,String snapshot){return execute(r,p,snapshot,value->{});}
    @Override public Outcome execute(DataResource r,Compiled p,String snapshot,Consumer<String> sink){
        Connection c=null;boolean commitAttempted=false;String encrypted=null;
        try{c=connect(r);c.setAutoCommit(false);c.setReadOnly(p.kind().equals("query"));
            if(p.kind().equals("query")){try(PreparedStatement st=c.prepareStatement(p.sql())){bind(st,p.parameters());st.setQueryTimeout(10);st.setMaxRows(1000);List<Map<String,Object>> rows=new ArrayList<>();boolean truncated=false;int size=0;try(ResultSet rs=st.executeQuery()){while(rs.next()){Map<String,Object> row=row(rs);size+=json.writeValueAsBytes(row).length;if(size>262144){truncated=true;break;}rows.add(row);}}c.rollback();Map<String,Object> result=new LinkedHashMap<>();result.put("rows",rows);result.put("returnedRows",rows.size());result.put("truncated",truncated);result.put("offset",p.ir().path("offset").asInt(0));if(p.ir().path("includeRowHashes").asBoolean())result.put("rowHashes",rows.stream().map(row->rowsHash(List.of(row))).toList());return new Outcome("SUCCEEDED",result,null);}}
            if(p.kind().equals("migration")){JsonNode steps=p.ir().path("_sql");for(JsonNode step:steps)try(Statement st=c.createStatement()){st.setQueryTimeout(10);st.execute(step.asText());}commitAttempted=true;c.commit();return new Outcome("COMMITTED",Map.of("schemaChanged",true,"affectedRows",0),null);}
            JsonNode meta=p.ir().get("_table");Map<String,JsonNode> cols=columns(meta);String op=p.ir().path("operation").asText(),target=target(p.ir());List<Map<String,Object>> before=new ArrayList<>();
            if(!op.equals("insert")){List<Object> args=new ArrayList<>();String where=requiredFilters(p.ir(),cols,args);before=select(c,"SELECT * FROM "+target+where+keyOrder(meta)+" LIMIT 1001 FOR UPDATE",args);if(before.size()>1000||before.size()!=p.ir().path("expectedRows").asInt()){c.rollback();return Outcome.failed("EXPECTED_ROWS_MISMATCH");}if(p.ir().has("expectedBeforeHash")&&!p.ir().get("expectedBeforeHash").asText().equals(rowsHash(before))){c.rollback();return new Outcome("FAILED_PRECONDITION",Map.of("errorCode","ROW_VERSION_CONFLICT"),null);}}
            List<Map<String,Object>> after=new ArrayList<>();int affected;
            try(PreparedStatement st=op.equals("insert")?c.prepareStatement(p.sql(),primary(meta).toArray(String[]::new)):c.prepareStatement(p.sql())){bind(st,p.parameters());st.setQueryTimeout(10);affected=st.executeUpdate();if(affected!=p.ir().path("expectedRows").asInt()){c.rollback();return Outcome.failed("EXPECTED_ROWS_MISMATCH");}
                if(op.equals("insert")){Map<String,Object> key=new LinkedHashMap<>();for(String k:primary(meta))if(p.ir().path("values").has(k))key.put(k,typed(cols.get(k),p.ir().path("values").get(k),false));try(ResultSet keys=st.getGeneratedKeys()){if(keys.next())for(String k:primary(meta))if(!key.containsKey(k))key.put(k,keys.getObject(k));}if(key.size()!=primary(meta).size())throw new IllegalStateException("insert key unavailable");after.addAll(byKey(c,target,meta,key));}
                else if(op.equals("update"))for(Map<String,Object> row:before)after.addAll(byKey(c,target,meta,row));
            }
            if(!op.equals("delete")&&after.size()!=affected)throw new IllegalStateException("post-image unavailable");
            ObjectNode recovery=json.createObjectNode().put("provider","postgres").put("resourceId",r.id.toString()).put("resourceVersion",r.resourceVersion).put("schema",p.ir().path("schema").asText()).put("table",p.ir().path("table").asText()).put("operation",op).put("expiresAt",System.currentTimeMillis()+7L*86400000L);recovery.set("tableMetadata",meta);recovery.set("before",json.valueToTree(before));recovery.set("after",json.valueToTree(after));recovery.put("beforeHash",rowsHash(before)).put("afterHash",rowsHash(after));String plain=recovery.toString();if(plain.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>262144)throw new IllegalStateException("snapshot exceeds bound");encrypted=secrets.seal(plain);sink.accept(encrypted);
            commitAttempted=true;c.commit();return new Outcome("COMMITTED",Map.of("affectedRows",affected,"beforeHash",rowsHash(before),"afterHash",rowsHash(after),"recoveryAvailable",true),encrypted);
        }catch(Exception e){if(commitAttempted)return new Outcome("COMMIT_UNKNOWN",Map.of("errorCode","COMMIT_RESULT_UNKNOWN"),encrypted);if(c!=null)try{c.rollback();}catch(SQLException failure){return new Outcome("COMMIT_UNKNOWN",Map.of("errorCode","ROLLBACK_UNCONFIRMED"),encrypted);}return Outcome.failed("DATABASE_EXECUTION_FAILED");}
        finally{if(c!=null)try{c.close();}catch(SQLException ignored){}}
    }
    @Override public Outcome compensate(DataResource r,String encrypted){Connection c=null;boolean commitAttempted=false;try{JsonNode snap=json.readTree(secrets.unseal(encrypted));if(!snap.path("provider").asText().equals("postgres")||!snap.path("resourceId").asText().equals(r.id.toString())||snap.path("resourceVersion").asLong(-1)!=r.resourceVersion||snap.path("expiresAt").asLong(0)<=System.currentTimeMillis())return new Outcome("COMPENSATION_CONFLICT",Map.of("errorCode","RECOVERY_SCOPE_OR_EXPIRY"),null);
            JsonNode live=table(schema(r),snap.path("schema").asText(),snap.path("table").asText()),meta=snap.path("tableMetadata");if(!DataPolicy.canonical(live).equals(DataPolicy.canonical(meta)))return new Outcome("COMPENSATION_CONFLICT",Map.of("errorCode","RECOVERY_SCHEMA_CONFLICT"),null);
            c=connect(r);c.setAutoCommit(false);String target=DataPolicy.identifier(snap.path("schema").asText())+"."+DataPolicy.identifier(snap.path("table").asText());List<Map<String,Object>> before=json.convertValue(snap.get("before"),List.class),after=json.convertValue(snap.get("after"),List.class);List<Map<String,Object>> expected=after.isEmpty()?before:after;List<Map<String,Object>> current=new ArrayList<>();for(Map<String,Object> row:expected)current.addAll(byKey(c,target,meta,row));String operation=snap.path("operation").asText();
            if(operation.equals("delete")?!current.isEmpty():!rowsHash(current).equals(snap.path("afterHash").asText())){c.rollback();return new Outcome("COMPENSATION_CONFLICT",Map.of("errorCode","RECOVERY_ROW_CONFLICT"),null);}
            Map<String,JsonNode> cols=columns(meta);List<String> keys=primary(meta);
            if(operation.equals("insert")){for(Map<String,Object> row:after){List<Object> params=new ArrayList<>();String predicate=keyPredicate(meta,row,params);try(PreparedStatement st=c.prepareStatement("DELETE FROM "+target+predicate)){bind(st,params);st.setQueryTimeout(10);if(st.executeUpdate()!=1)throw new IllegalStateException();}}}
            else for(Map<String,Object> row:before){List<String> names=new ArrayList<>();boolean identity=false;for(String name:cols.keySet()){JsonNode col=cols.get(name);if(operation.equals("delete")?!col.path("computed").asBoolean():!col.path("generated").asBoolean()&&!keys.contains(name))names.add(name);identity|=col.path("autoIncrement").asBoolean();}List<Object> params=new ArrayList<>();for(String name:names)params.add(typed(cols.get(name),json.valueToTree(row.get(name)),true));String sql;if(operation.equals("delete"))sql="INSERT INTO "+target+" ("+String.join(", ",names.stream().map(DataPolicy::identifier).toList())+")"+(identity?" OVERRIDING SYSTEM VALUE":"")+" VALUES ("+String.join(", ",Collections.nCopies(names.size(),"?"))+")";else sql="UPDATE "+target+" SET "+String.join(", ",names.stream().map(n->DataPolicy.identifier(n)+" = ?").toList())+keyPredicate(meta,row,params);try(PreparedStatement st=c.prepareStatement(sql)){bind(st,params);st.setQueryTimeout(10);if(st.executeUpdate()!=1)throw new IllegalStateException();}}
            // Identity values must be restored explicitly. Computed columns and triggers
            // can alter restored values, so check the complete preimage before committing.
            List<Map<String,Object>> restored=new ArrayList<>();for(Map<String,Object> row:expected)restored.addAll(byKey(c,target,meta,row));
            if(operation.equals("insert")?!restored.isEmpty():!rowsHash(restored).equals(snap.path("beforeHash").asText())){c.rollback();return new Outcome("COMPENSATION_CONFLICT",Map.of("errorCode","RECOVERY_RESTORED_IMAGE_MISMATCH"),null);}
            commitAttempted=true;c.commit();return new Outcome("COMPENSATED",Map.of("restored",true,"affectedRows",expected.size()),null);
        }catch(Exception e){if(commitAttempted)return new Outcome("COMPENSATION_UNKNOWN",Map.of("errorCode","RECOVERY_COMMIT_UNKNOWN"),null);if(c!=null)try{c.rollback();}catch(SQLException failure){return new Outcome("COMPENSATION_UNKNOWN",Map.of("errorCode","RECOVERY_ROLLBACK_UNKNOWN"),null);}return new Outcome("COMPENSATION_CONFLICT",Map.of("errorCode","RECOVERY_PRECONDITION_FAILED"),null);}finally{if(c!=null)try{c.close();}catch(SQLException ignored){}}}
    private String target(JsonNode ir){return DataPolicy.identifier(ir.path("schema").asText())+"."+DataPolicy.identifier(ir.path("table").asText());}
    private List<String> primary(JsonNode meta){List<String> keys=new ArrayList<>();meta.path("primaryKey").forEach(n->keys.add(n.asText()));return keys;}
    private String keyOrder(JsonNode meta){return " ORDER BY "+String.join(", ",primary(meta).stream().map(DataPolicy::identifier).toList());}
    private String keyPredicate(JsonNode meta,Map<String,Object> row,List<Object> params){Map<String,JsonNode> cols=columns(meta);List<String> predicates=new ArrayList<>();for(String pk:primary(meta)){predicates.add(DataPolicy.identifier(pk)+" = ?");params.add(typed(cols.get(pk),json.valueToTree(row.get(pk)),false));}return " WHERE "+String.join(" AND ",predicates);}
    private List<Map<String,Object>> byKey(Connection c,String target,JsonNode meta,Map<String,Object> row)throws Exception{List<Object> params=new ArrayList<>();return select(c,"SELECT * FROM "+target+keyPredicate(meta,row,params)+" FOR UPDATE",params);}
    private List<Map<String,Object>> select(Connection c,String sql,List<Object> params)throws Exception{try(PreparedStatement st=c.prepareStatement(sql)){bind(st,params);st.setQueryTimeout(10);st.setMaxRows(1001);List<Map<String,Object>> rows=new ArrayList<>();int bytes=0;try(ResultSet rs=st.executeQuery()){while(rs.next()){Map<String,Object> row=row(rs);bytes+=json.writeValueAsBytes(row).length;if(bytes>262144)throw new IllegalStateException("row image bound exceeded");rows.add(row);}}return rows;}}
    private Map<String,Object> row(ResultSet rs)throws SQLException{Map<String,Object> row=new LinkedHashMap<>();for(int i=1;i<=rs.getMetaData().getColumnCount();i++){Object v=rs.getObject(i);if(v instanceof java.sql.Date d)v=d.toLocalDate().toString();else if(v instanceof java.sql.Time t)v=t.toLocalTime().toString();else if(v instanceof java.sql.Timestamp t)v=t.toLocalDateTime().toString();else if(v instanceof BigDecimal n)v=n.toPlainString();else if(v instanceof Long n&&(n>9007199254740991L||n< -9007199254740991L))v=n.toString();else if(v!=null&&!(v instanceof Number)&&!(v instanceof Boolean)&&!(v instanceof String))v=v.toString();row.put(rs.getMetaData().getColumnLabel(i),v);}return row;}
    private String rowsHash(List<Map<String,Object>> rows){return DataPolicy.hash(DataPolicy.canonical(json.valueToTree(rows)));}
    public Map<String,Object> explain(DataResource r,Compiled p){if(!p.kind().equals("query"))throw DataPolicy.bad("only read query EXPLAIN is supported");try(Connection c=connect(r)){c.setReadOnly(true);try(PreparedStatement s=c.prepareStatement("EXPLAIN (FORMAT JSON) "+p.sql())){bind(s,p.parameters());s.setQueryTimeout(10);try(ResultSet rows=s.executeQuery()){return Map.of("plan",rows.next()?rows.getString(1):"");}}}catch(Exception e){throw DataPolicy.bad("EXPLAIN failed");}}
    private void bind(PreparedStatement st,List<Object> args)throws SQLException{for(int i=0;i<args.size();i++)st.setObject(i+1,args.get(i));}
    private Compiled migration(DataResource r,JsonNode schema,JsonNode ir){DataPolicy.fields(ir,"kind","schema","steps");String sn=DataPolicy.required(ir,"schema");boolean allowed=false;try{for(JsonNode s:json.readTree(r.allowedSchemas))allowed|=sn.equals(s.asText());}catch(Exception e){throw DataPolicy.bad("invalid schema allowlist");}if(!allowed)throw DataPolicy.forbidden();DataPolicy.identifier(sn);JsonNode steps=ir.get("steps");if(steps==null||!steps.isArray()||steps.isEmpty()||steps.size()>8)throw DataPolicy.bad("migration requires 1 to 8 steps");List<String> sql=new ArrayList<>();Set<String> newlyCreated=new HashSet<>();
        for(JsonNode step:steps){String operation=DataPolicy.required(step,"operation"),name=DataPolicy.required(step,"table"),target=DataPolicy.identifier(sn)+"."+DataPolicy.identifier(name);if(operation.equals("create_table")){DataPolicy.fields(step,"operation","table","columns","primaryKey");for(JsonNode t:schema.path("tables"))if(sn.equals(t.path("schema").asText())&&name.equals(t.path("name").asText()))throw DataPolicy.bad("table already exists");if(!newlyCreated.add(name))throw DataPolicy.bad("duplicate table creation");JsonNode columns=step.get("columns");if(columns==null||!columns.isArray()||columns.isEmpty()||columns.size()>32)throw DataPolicy.bad("create_table requires 1 to 32 columns");List<String> definitions=new ArrayList<>();Set<String> names=new HashSet<>();for(JsonNode col:columns){DataPolicy.fields(col,"name","type","nullable");String column=DataPolicy.required(col,"name");if(!names.add(column))throw DataPolicy.bad("duplicate column");if(col.has("nullable")&&!col.get("nullable").isBoolean())throw DataPolicy.bad("nullable must be boolean");definitions.add(DataPolicy.identifier(column)+" "+ddlType(col)+(col.path("nullable").asBoolean(true)?"":" NOT NULL"));}JsonNode pk=step.get("primaryKey");if(pk==null||!pk.isArray()||pk.isEmpty()||pk.size()>4)throw DataPolicy.bad("create_table requires a bounded primary key");List<String> keys=new ArrayList<>();Set<String> distinct=new HashSet<>();for(JsonNode k:pk){if(!k.isTextual()||!names.contains(k.asText())||!distinct.add(k.asText()))throw DataPolicy.bad("unknown/duplicate primary key");keys.add(DataPolicy.identifier(k.asText()));}definitions.add("PRIMARY KEY ("+String.join(", ",keys)+")");sql.add("CREATE TABLE "+target+" ("+String.join(", ",definitions)+")");}
            else if(operation.equals("add_column")){DataPolicy.fields(step,"operation","table","column");JsonNode meta=table(schema,sn,name),col=step.get("column");DataPolicy.fields(col,"name","type","nullable");if(col.has("nullable")&&(!col.get("nullable").isBoolean()||!col.get("nullable").booleanValue()))throw DataPolicy.bad("add_column supports nullable columns only");String column=DataPolicy.required(col,"name");if(columns(meta).containsKey(column))throw DataPolicy.bad("column already exists");sql.add("ALTER TABLE "+target+" ADD COLUMN "+DataPolicy.identifier(column)+" "+ddlType(col));}
            else if(operation.equals("create_index")){DataPolicy.fields(step,"operation","table","name","columns");JsonNode meta=table(schema,sn,name);String index=DataPolicy.required(step,"name");JsonNode cs=step.get("columns");if(cs==null||!cs.isArray()||cs.isEmpty()||cs.size()>4)throw DataPolicy.bad("index requires 1 to 4 columns");List<String> names=new ArrayList<>();for(JsonNode col:cs){if(!col.isTextual())throw DataPolicy.bad("index column must be string");names.add(column(columns(meta),col.asText()));}sql.add("CREATE INDEX "+DataPolicy.identifier(index)+" ON "+target+" ("+String.join(", ",names)+")");}
            else throw DataPolicy.bad("only create_table, nullable add_column and ordinary create_index are supported");}
        ObjectNode intent=(ObjectNode)ir.deepCopy();intent.set("_sql",json.valueToTree(sql));return new Compiled("migration",String.join(";\n",sql),"",List.of(),intent);
    }
    private String ddlType(JsonNode column){return switch(DataPolicy.required(column,"type")){case "text"->"TEXT";case "integer"->"INTEGER";case "bigint"->"BIGINT";case "boolean"->"BOOLEAN";case "date"->"DATE";case "timestamp"->"TIMESTAMP";case "uuid"->"UUID";default->throw DataPolicy.bad("unsupported migration column type");};}
}
